import{_ as i,o as t,c as n,a2 as l}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Version 1.0.0.25 Launched","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.25-launched.md","filePath":"change-log/release/version-1.0.0.25-launched.md"}'),r={name:"change-log/release/version-1.0.0.25-launched.md"};function o(a,e,s,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="version-1-0-0-25-launched" tabindex="-1">Version 1.0.0.25 Launched <a class="header-anchor" href="#version-1-0-0-25-launched" aria-label="Permalink to &quot;Version 1.0.0.25 Launched&quot;">​</a></h1><p>29th May 2025</p><p><strong>Major New Broker Addition &amp; Enhancements:</strong></p><ul><li><strong>Tradejini</strong></li><li><strong>Groww</strong></li><li><strong>Dhan (Sandbox)</strong></li></ul><p><strong>Major New Features &amp; System Enhancements:</strong></p><ul><li><strong>Full WebSocket Implementation (Pilot Testing with Angel):</strong><ul><li>Introduced robust WebSocket support for real-time market data streaming.</li><li>Delivers LTP (Last Traded Price), Quotes, and full Market Depth (including Top 5 Bid/Ask).</li><li>Includes server-side (server.py) and Nginx configuration for WebSocket proxying on Ubuntu.</li><li>Added necessary WebSocket host, port, and URL configurations to .sample.env.</li><li>Provided WebSocket usage examples (e.g., stoploss example).</li><li>Fixes implemented for subscription mode isolation and JSON deserialization error handling.</li><li>Addressed issues such as &quot;No. of Orders in the Depth&quot; display.</li></ul></li><li><strong>Docker Build Optimization:</strong><ul><li>Implemented <strong>multi-stage builds</strong> for Docker, significantly reducing the final Docker image size.</li></ul></li><li><strong>Enhanced Connection Pooling:</strong><ul><li>Rolled out and fixed shared connection pooling for Data APIs, Order APIs, Authentication, Funds, and Master Contract services across applicable brokers, improving performance and resource management.</li></ul></li><li><strong>Database Enhancements:</strong><ul><li>Integrated SQLiteDB for storing IST (Indian Standard Time) data.</li><li>Added DuckDB library support and functionality for efficient intraday data downloads.</li></ul></li></ul><p>🔧 <strong>Broker-Specific Fixes &amp; Enhancements (Recent):</strong></p><ul><li><strong>AngelOne:</strong><ul><li>Angel Average Price Fix (related to WebSocket data).</li><li>Added Angel UserID to the AuthDB for enhanced WebSocket authentication.</li></ul></li><li><strong>Fyers:</strong><ul><li>Fine-tuned Master Contract Data for missing SENSEX index. (Assuming this was a recent touch-up)</li></ul></li><li><strong>ICICI:</strong><ul><li>Removed ICICI integration and removed relevant references</li></ul></li><li><strong>Fivepaisa:</strong><ul><li>Recent general updates and fixes to order APIs, common symbols, order status, master contract DB.</li></ul></li><li><strong>XTS API Supported Brokers (General):</strong><ul><li>Refined scripts and processes for XTS Based Market Data Credentials setup.</li></ul></li></ul><p><strong>Common Symbol Format Now Implemented/Enhanced For:</strong></p><ul><li><strong>Tradejini (New)</strong></li><li><strong>Groww</strong></li><li><strong>Aliceblue</strong></li><li>Fyers</li><li>Dhan</li><li>Dhan(Sandbox)</li><li>Zerodha</li><li>Flattrade</li><li>Shoonya (BSE indices not available)</li><li>Compositedge</li><li>AngelOne</li><li>Upstox</li><li>Paytm</li><li>Pocketful</li><li>Jainam (XTS API)</li><li>IIFL (XTS API)</li><li>Wisdom Capital (XTS API)</li><li>5paisa (XTS API)</li><li>5paisa </li></ul><p>⚙️ <strong>System Architecture &amp; Further Enhancements:</strong></p><ul><li><strong>API &amp; Service Layer:</strong><ul><li>Integrated a dedicated Service Layer with the Restx API Layer for better modularity.</li><li>Fixed socket emitting event errors, mitigating potential rate limiting issues.</li></ul></li><li><strong>Dependency Management &amp; Environment:</strong><ul><li>Updated core libraries: tornado and flask-cors (crucial for WebSocket and API layers).</li><li>Adopted and updated configurations for the UV package manager (e.g., uv.lock updates).</li><li>Upgraded key dependencies like httpcore (to 1.0.9), setuptools (security fix), and h11 library.</li><li>Updated requirements.txt and websockets.txt to reflect new and updated dependencies.</li></ul></li><li><strong>Security &amp; Deployment:</strong><ul><li>Implemented/Updated CORS (Cross-Origin Resource Sharing) and CSP (Content Security Policy) configurations.</li><li>Updated Ubuntu server shell scripts and installation scripts, including improved support for UV.</li></ul></li></ul><p><strong>Documentation &amp; DevOps Updates:</strong></p><ul><li><strong>New &amp; Updated Docs:</strong><ul><li>Comprehensive documentation for the new WebSocket implementation.</li><li>Documentation updates related to the Tradejini integration.</li><li>Added internal assessment and broker design documents.</li></ul></li><li><strong>Configuration &amp; Testing:</strong><ul><li>Updated .sample.env file with WebSocket configurations and new settings (e.g., for Cloudflare insights).</li><li>Added significant new test code for WebSocket features and other enhancements.</li><li>Updates to the general Docker build process to reflect multi-stage builds.</li></ul></li></ul>',14)])])}const m=i(r,[["render",o]]);export{p as __pageData,m as default};
